SourceCode.Declaration:
/// <summary>
/// Code jobs for users.
/// </summary>
class OLK_EnvironmentDataSetupExecuteCode_System extends OLK_EnvironmentDataSetupExecuteCode
{
}

Method.Source:
[OLK_EnvironmentDataSetupAttribute('Enable all disabled users.')]
public void enableUsersAll()
{
    UserInfo userInfo;

    ttsbegin;

    while select forupdate userInfo
        where userInfo.enable == 0
    {
        userInfo.enable = 1;
        userInfo.update();
    }

    ttscommit;
}

[OLK_EnvironmentDataSetupAttribute('Enable the users listed in the EnableUsersList default value.')]
public void enableUsersList()
{
    ListEnumerator  users = OLK_EnvironmentDataSetupDefaultValues::valueList(OLK_EnvironmentDataSetupDefaultData::EnableUsersList).getEnumerator();
    UserInfo        userInfo;

    ttsbegin;

    while (users.moveNext())
    {
        UserId userId = users.current();

        select forupdate firstonly userInfo
            where userInfo.id     == userId
               && userInfo.enable == 0;

        if (userInfo.RecId)
        {
            userInfo.enable = 1;
            userInfo.update();
        }
    }

    ttscommit;
}
